//! Verification of TSP packages.
//!
//! Everything is treated as untrusted: entry names, symlinks, declared sizes
//! and the manifest itself. Nothing is extracted to disk or executed;
//! contents are read in streaming mode only to compute hashes.
//!
//! This verification proves the *internal* consistency of the package. Without a signature
//! (not implemented yet), it proves neither authorship nor that the package was not
//! fully regenerated by whoever modified it.

use crate::inventory::logical_digest;
use crate::model::*;
use crate::policy::{self, MAX_POLICY_BYTES, Policy};
use crate::util::{hash_reader, hex_sha256, is_safe_rel_path, is_sha256_hex};
use anyhow::{Context, Result, bail};
use serde::Serialize;
use std::collections::{BTreeMap, BTreeSet};
use std::fs::File;
use std::io::Read;
use std::path::Path;
use zip::ZipArchive;

pub const MAX_MANIFEST_BYTES: u64 = 16 * 1024 * 1024;
pub const MAX_INVENTORY_BYTES: u64 = 512 * 1024 * 1024;
pub const MAX_SMALL_ENTRY_BYTES: u64 = 64 * 1024 * 1024;

#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum VerifyStatus {
    Valid,
    FailedIntegrity,
    /// Integrity is fine, but the contents violate the export policy embedded in the package.
    PolicyViolation,
    InvalidPackage,
}

#[derive(Debug, Clone, Serialize)]
pub struct Modified {
    pub path: String,
    pub expected_sha256: String,
    pub actual_sha256: Option<String>,
    pub expected_size: u64,
    pub actual_size: Option<u64>,
    pub note: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct VerifyReport {
    pub status: VerifyStatus,
    pub files_checked: usize,
    /// Internal package paths (e.g. `source/Assets/a.cs`).
    pub missing: Vec<String>,
    pub modified: Vec<Modified>,
    pub unexpected: Vec<String>,
    pub integrity_errors: Vec<String>,
    pub schema_errors: Vec<String>,
    /// Files in `source/` that the embedded policy does not allow exporting.
    pub policy_violations: Vec<String>,
    /// Signatures do not exist yet in this version.
    pub signature: &'static str,
}

impl VerifyReport {
    fn new() -> Self {
        VerifyReport {
            status: VerifyStatus::InvalidPackage,
            files_checked: 0,
            missing: vec![],
            modified: vec![],
            unexpected: vec![],
            integrity_errors: vec![],
            schema_errors: vec![],
            policy_violations: vec![],
            signature: "not_present",
        }
    }

    pub fn is_valid(&self) -> bool {
        self.status == VerifyStatus::Valid
    }
}

pub struct Verified {
    pub report: VerifyReport,
    pub manifest: Option<Manifest>,
    pub inventory: Option<IntegrityFile>,
}

pub fn verify_package(path: &Path) -> Result<VerifyReport> {
    Ok(verify_detailed(path)?.report)
}

fn finish(
    mut rep: VerifyReport,
    manifest: Option<Manifest>,
    inventory: Option<IntegrityFile>,
) -> Verified {
    rep.missing.sort();
    rep.modified.sort_by(|a, b| a.path.cmp(&b.path));
    rep.unexpected.sort();
    rep.status = if !rep.schema_errors.is_empty() {
        VerifyStatus::InvalidPackage
    } else if !(rep.missing.is_empty()
        && rep.modified.is_empty()
        && rep.unexpected.is_empty()
        && rep.integrity_errors.is_empty())
    {
        VerifyStatus::FailedIntegrity
    } else if !rep.policy_violations.is_empty() {
        VerifyStatus::PolicyViolation
    } else {
        VerifyStatus::Valid
    };
    Verified {
        report: rep,
        manifest,
        inventory,
    }
}

fn read_entry(archive: &mut ZipArchive<File>, idx: usize, limit: u64) -> Result<Vec<u8>> {
    let f = archive.by_index(idx)?;
    let mut buf = Vec::new();
    f.take(limit + 1).read_to_end(&mut buf)?;
    if buf.len() as u64 > limit {
        bail!("entry exceeds the limit of {limit} bytes");
    }
    Ok(buf)
}

/// Reads a small package entry by name (also used by `report`).
pub fn read_named_entry(path: &Path, name: &str, limit: u64) -> Result<Option<Vec<u8>>> {
    let file = File::open(path).with_context(|| format!("could not open {}", path.display()))?;
    let mut archive = ZipArchive::new(file)?;
    let Some(idx) = archive.index_for_name(name) else {
        return Ok(None);
    };
    Ok(Some(read_entry(&mut archive, idx, limit)?))
}

pub fn verify_detailed(path: &Path) -> Result<Verified> {
    let file = File::open(path).with_context(|| format!("could not open {}", path.display()))?;
    let mut rep = VerifyReport::new();

    let mut archive = match ZipArchive::new(file) {
        Ok(a) => a,
        Err(e) => {
            rep.schema_errors.push(format!("invalid ZIP file: {e}"));
            return Ok(finish(rep, None, None));
        }
    };

    // 1. Entry table: safe names, no duplicates, no symlinks.
    let mut entries: BTreeMap<String, usize> = BTreeMap::new();
    for i in 0..archive.len() {
        let (name, is_dir, mode) = match archive.by_index_raw(i) {
            Ok(f) => (f.name().to_string(), f.is_dir(), f.unix_mode()),
            Err(e) => {
                rep.schema_errors
                    .push(format!("entry #{i} unreadable: {e}"));
                continue;
            }
        };
        let trimmed = name.strip_suffix('/').unwrap_or(&name);
        if !is_safe_rel_path(trimmed) {
            rep.schema_errors
                .push(format!("unsafe entry name: {name:?}"));
            continue;
        }
        if mode.is_some_and(|m| m & 0o170000 == 0o120000) {
            rep.schema_errors
                .push(format!("entry is a symlink (forbidden): {name:?}"));
            continue;
        }
        if is_dir {
            continue;
        }
        if entries.insert(name.clone(), i).is_some() {
            rep.schema_errors.push(format!("duplicate entry: {name:?}"));
        }
    }

    // 2. Manifesto.
    let Some(&manifest_idx) = entries.get(MANIFEST_PATH) else {
        rep.schema_errors.push(format!("{MANIFEST_PATH} missing"));
        return Ok(finish(rep, None, None));
    };
    let manifest: Manifest = match read_entry(&mut archive, manifest_idx, MAX_MANIFEST_BYTES)
        .map_err(|e| e.to_string())
        .and_then(|b| serde_json::from_slice(&b).map_err(|e| e.to_string()))
    {
        Ok(m) => m,
        Err(e) => {
            rep.schema_errors.push(format!("invalid manifest: {e}"));
            return Ok(finish(rep, None, None));
        }
    };
    rep.schema_errors
        .extend(validate_manifest(&manifest, &entries));

    // 3. Integrity inventory.
    let inv_path = manifest.integrity.inventory_path.clone();
    let Some(&inv_idx) = entries.get(&inv_path) else {
        // validate_manifest already recorded the absence/unsafety.
        return Ok(finish(rep, Some(manifest), None));
    };
    let inv_bytes = match read_entry(&mut archive, inv_idx, MAX_INVENTORY_BYTES) {
        Ok(b) => b,
        Err(e) => {
            rep.schema_errors.push(format!("inventory unreadable: {e}"));
            return Ok(finish(rep, Some(manifest), None));
        }
    };
    if hex_sha256(&inv_bytes) != manifest.integrity.inventory_sha256 {
        rep.integrity_errors.push(format!(
            "the SHA-256 of {inv_path} differs from the one recorded in the manifest"
        ));
    }
    let inventory: IntegrityFile = match serde_json::from_slice(&inv_bytes) {
        Ok(i) => i,
        Err(e) => {
            rep.schema_errors.push(format!("invalid inventory: {e}"));
            return Ok(finish(rep, Some(manifest), None));
        }
    };
    if !validate_inventory(&inventory, &manifest, &mut rep) {
        return Ok(finish(rep, Some(manifest), Some(inventory)));
    }

    // 4. Contents: missing, modified, unexpected.
    let mut expected: BTreeSet<String> = BTreeSet::new();
    expected.insert(MANIFEST_PATH.to_string());
    expected.insert(inv_path);

    for f in &inventory.files {
        let name = format!("{SOURCE_PREFIX}{}", f.path);
        expected.insert(name.clone());
        rep.files_checked += 1;
        match entries.get(&name) {
            None => rep.missing.push(name),
            Some(&idx) => check_entry(&mut archive, idx, &name, &f.sha256, f.size, &mut rep),
        }
    }
    for m in &manifest.metadata_files {
        expected.insert(m.path.clone());
        rep.files_checked += 1;
        match entries.get(&m.path) {
            None => rep.missing.push(m.path.clone()),
            Some(&idx) => check_entry(&mut archive, idx, &m.path, &m.sha256, m.size, &mut rep),
        }
    }
    for name in entries.keys() {
        if !expected.contains(name) {
            rep.unexpected.push(name.clone());
        }
    }

    // 5. Conformance with the embedded export policy (separate from integrity).
    if let Some(policy_path) = &manifest.policy_ref
        && let Some(&idx) = entries.get(policy_path)
    {
        check_policy_conformance(&mut archive, idx, &inventory, &mut rep);
    }

    Ok(finish(rep, Some(manifest), Some(inventory)))
}

fn check_policy_conformance(
    archive: &mut ZipArchive<File>,
    idx: usize,
    inventory: &IntegrityFile,
    rep: &mut VerifyReport,
) {
    let bytes = match read_entry(archive, idx, MAX_POLICY_BYTES) {
        Ok(b) => b,
        Err(e) => {
            rep.schema_errors
                .push(format!("embedded policy unreadable: {e}"));
            return;
        }
    };
    let policy = match Policy::parse(&bytes) {
        Ok(p) => p,
        Err(errs) => {
            for e in errs {
                rep.schema_errors
                    .push(format!("embedded policy invalid: {e}"));
            }
            return;
        }
    };
    for o in policy::apply(&policy, &inventory.files).omitted {
        rep.policy_violations.push(format!(
            "{SOURCE_PREFIX}{}: component {:?} cannot be exported under the embedded policy",
            o.path, o.component
        ));
    }
}

fn check_entry(
    archive: &mut ZipArchive<File>,
    idx: usize,
    name: &str,
    expected_sha: &str,
    expected_size: u64,
    rep: &mut VerifyReport,
) {
    // Reads at most size+1 bytes: a ZIP cannot force unbounded reads.
    let res = archive
        .by_index(idx)
        .map_err(|e| e.to_string())
        .and_then(|f| {
            hash_reader(f.take(expected_size.saturating_add(1))).map_err(|e| e.to_string())
        });
    match res {
        Ok((h, n)) if h == expected_sha && n == expected_size => {}
        Ok((h, n)) => rep.modified.push(Modified {
            path: name.to_string(),
            expected_sha256: expected_sha.to_string(),
            actual_sha256: Some(h),
            expected_size,
            actual_size: Some(n),
            note: (n > expected_size)
                .then(|| "content larger than declared (read truncated)".to_string()),
        }),
        Err(e) => rep.modified.push(Modified {
            path: name.to_string(),
            expected_sha256: expected_sha.to_string(),
            actual_sha256: None,
            expected_size,
            actual_size: None,
            note: Some(format!("read failure: {e}")),
        }),
    }
}

fn validate_manifest(m: &Manifest, entries: &BTreeMap<String, usize>) -> Vec<String> {
    let mut e: Vec<String> = Vec::new();

    if m.format != FORMAT {
        e.push(format!("format must be {FORMAT:?}, found {:?}", m.format));
    }
    if !SUPPORTED_VERSIONS.contains(&m.format_version.as_str()) {
        e.push(format!(
            "format_version {:?} unknown (supported: {})",
            m.format_version,
            SUPPORTED_VERSIONS.join(", ")
        ));
    }
    if m.project.name.trim().is_empty() {
        e.push("project.name is empty".into());
    }
    if m.integrity.algorithm != "sha256" {
        e.push(format!(
            "integrity.algorithm {:?} not supported (expected sha256)",
            m.integrity.algorithm
        ));
    }
    if !is_safe_rel_path(&m.integrity.inventory_path) {
        e.push(format!(
            "integrity.inventory_path unsafe: {:?}",
            m.integrity.inventory_path
        ));
    } else if !entries.contains_key(&m.integrity.inventory_path) {
        e.push(format!(
            "inventory {:?} does not exist in the package",
            m.integrity.inventory_path
        ));
    }
    for (field, v) in [
        ("integrity.inventory_sha256", &m.integrity.inventory_sha256),
        (
            "integrity.logical_inventory_sha256",
            &m.integrity.logical_inventory_sha256,
        ),
    ] {
        if !is_sha256_hex(v) {
            e.push(format!("{field} malformed"));
        }
    }

    // metadata_files
    let mut meta_paths: BTreeSet<&str> = BTreeSet::new();
    for f in &m.metadata_files {
        if !is_safe_rel_path(&f.path) {
            e.push(format!("metadata_files: unsafe path {:?}", f.path));
            continue;
        }
        if f.path == MANIFEST_PATH
            || f.path == m.integrity.inventory_path
            || f.path.starts_with(SOURCE_PREFIX)
        {
            e.push(format!("metadata_files: reserved path {:?}", f.path));
        }
        if !is_sha256_hex(&f.sha256) {
            e.push(format!("metadata_files: malformed hash in {:?}", f.path));
        }
        if !meta_paths.insert(f.path.as_str()) {
            e.push(format!("metadata_files: duplicate path {:?}", f.path));
        }
    }

    // componentes
    let mut ids: BTreeSet<&str> = BTreeSet::new();
    let mut refs: Vec<(String, &str)> = Vec::new();
    for c in &m.components {
        if !ids.insert(c.id.as_str()) {
            e.push(format!("duplicate component: {:?}", c.id));
        }
        if !REDISTRIBUTION_STATES.contains(&c.redistribution.as_str()) {
            e.push(format!(
                "component {:?}: invalid redistribution {:?}",
                c.id, c.redistribution
            ));
        }
        if let Some(p) = &c.path {
            let trimmed = p.strip_suffix('/').unwrap_or(p);
            if !is_safe_rel_path(trimmed) {
                e.push(format!("component {:?}: unsafe path {p:?}", c.id));
            } else if c.redistribution == "not_permitted" {
                let prefix = format!("{trimmed}/");
                if entries
                    .keys()
                    .any(|k| k == trimmed || k.starts_with(&prefix))
                {
                    e.push(format!(
                        "blocked component included in the package: {:?} ({p})",
                        c.id
                    ));
                }
            }
        }
        if let Some(r) = &c.provenance_ref {
            refs.push((format!("component {:?}: provenance_ref", c.id), r));
        }
        if let Some(r) = &c.instructions_ref {
            refs.push((format!("component {:?}: instructions_ref", c.id), r));
        }
        if let Some(r) = &c.external_ref {
            refs.push((format!("component {:?}: external_ref", c.id), r));
        }
        if let Some(o) = &c.origin_path
            && !is_safe_rel_path(o)
        {
            e.push(format!("component {:?}: unsafe origin_path {o:?}", c.id));
        }
    }
    if let Some(p) = &m.policy_ref {
        refs.push(("policy_ref".to_string(), p));
    }

    // reprodutibilidade
    let r = &m.reproducibility;
    for (what, v) in [
        ("reproducibility.environment", &r.environment),
        ("reproducibility.build_recipe", &r.build_recipe),
        ("reproducibility.test_plan", &r.test_plan),
    ] {
        if let Some(p) = v {
            refs.push((what.to_string(), p));
        }
    }
    if !RESTORATION_STATES.contains(&r.restoration.status.as_str()) {
        e.push(format!(
            "invalid restoration.status {:?}",
            r.restoration.status
        ));
    }
    if r.restoration.status == "success" {
        match &r.restoration.evidence_ref {
            Some(p) => refs.push(("restoration.evidence_ref".to_string(), p)),
            None => {
                e.push("restoration.status=success without test evidence (evidence_ref)".into())
            }
        }
    }

    // Every reference must exist in the package and be protected by a hash.
    for (what, p) in refs {
        if !is_safe_rel_path(p) {
            e.push(format!("{what}: unsafe path {p:?}"));
        } else if !entries.contains_key(p) {
            e.push(format!("{what}: file does not exist in the package: {p:?}"));
        } else if !meta_paths.contains(p) {
            e.push(format!(
                "{what}: {p:?} is not listed in metadata_files (no hash)"
            ));
        }
    }
    e
}

/// Returns `false` if the inventory is structurally invalid (not worth verifying files).
fn validate_inventory(inv: &IntegrityFile, m: &Manifest, rep: &mut VerifyReport) -> bool {
    let before = rep.schema_errors.len();
    if inv.algorithm != "sha256" {
        rep.schema_errors.push(format!(
            "inventory: unsupported algorithm {:?}",
            inv.algorithm
        ));
    }
    if inv.root != SOURCE_PREFIX {
        rep.schema_errors.push(format!(
            "inventory: root must be {SOURCE_PREFIX:?}, found {:?}",
            inv.root
        ));
    }
    let mut seen: BTreeSet<&str> = BTreeSet::new();
    for f in &inv.files {
        if !is_safe_rel_path(&f.path) {
            rep.schema_errors
                .push(format!("inventory: unsafe path {:?}", f.path));
        } else if !seen.insert(f.path.as_str()) {
            rep.schema_errors
                .push(format!("inventory: duplicate path {:?}", f.path));
        }
        if !is_sha256_hex(&f.sha256) {
            rep.schema_errors
                .push(format!("inventory: malformed hash in {:?}", f.path));
        }
    }
    if rep.schema_errors.len() > before {
        return false;
    }

    let digest = logical_digest(&inv.files);
    if digest != inv.logical_inventory_sha256 {
        rep.integrity_errors.push(
            "the logical inventory digest does not match the one declared in files.json".into(),
        );
    }
    if digest != m.integrity.logical_inventory_sha256 {
        rep.integrity_errors.push(
            "the logical inventory digest does not match the one declared in the manifest".into(),
        );
    }
    let total: u64 = inv.files.iter().map(|f| f.size).sum();
    if inv.files.len() as u64 != m.integrity.file_count || total != m.integrity.total_bytes {
        rep.integrity_errors
            .push("the file/byte count of the inventory differs from the manifest".into());
    }
    true
}
